-- =========================================================
-- The 1,128 real startups (Startup Explorer, admin Startups page,
-- and the similar startups of an assessment)
-- Run once in Supabase: SQL Editor → paste → Run, after 0006_reference_data.
-- (Safe to run again: a startup that already exists is updated, not added twice.)
--
-- Made from seed/startups.csv (datasets/idea-similarity, sheet "Startups"),
-- tidied so the explorer's filters show a clean list:
--   sector        hidden characters removed, spelling fixed and similar names
--                 joined into one list of sectors, separated by ";"
--                 ("Financial Services" + "Fintech" → "Financial Services & Fintech")
--   region        Saudi cities written as a region become their region (Jeddah → Makkah)
--   stage         "N/A" removed; several stages are separated by ";"
--   website       "https://" added where it was missing; personal email
--                 addresses removed (they are not websites)
--   description   Gmail's own text, copied by mistake for 4 rows, removed
-- The logo column stays empty: the pages show the startup's initials.
-- =========================================================
insert into public.startups (startup_id, startup_name, startup_description, sector, target_market, products_services, stage, region, tags, website, ecosystemsa_profile_url, description_source, country) values
