('ST_629', 'Saif Check', 'The first AI risk assessment in MENA, founded by a medical doctor and AI governance specialist, SAIF CHECK brings the discipline of clinical safety, cybersecurity, and regulatory rigor to modern AI systems.', 'Cybersecurity; AI & Deep Tech', 'B2B', null, 'Pre-Series A', 'Riyadh', 'Compliance, AI, RegTech', 'https://saifcheck.ai/', 'https://ecosystemsa.com/modules/startups/2b0b3ab7-b54a-42f5-941f-7e44e210da4e', 'https://ecosystemsa.com/modules/startups/2b0b3ab7-b54a-42f5-941f-7e44e210da4e', 'Saudi Arabia'),
('ST_630', 'ELEVATY Skills', 'Elevaty is the digital partner for modern hotel operations. We replace outdated training manuals with a mobile-first platform that speaks the language of your staff. Our platform deconstructs complex hotel standards into simple, step-by-step visual tasks that can be mastered in minutes. Whether onboarding new staff for a Giga-project or maintaining standards in an established boutique hotel, Elevaty ensures your team is "Day-1 Ready," reducing supervisor workload and eliminating service errors.', 'Travel, Tourism & Hospitality; Education, Research & Talent', null, null, 'Pre-Seed', 'Riyadh', 'tutorial videos, hospitality operations', 'https://elevaty.co/', 'https://ecosystemsa.com/modules/startups/06564dc8-4286-4c83-8a38-94d4226216ac', 'https://ecosystemsa.com/modules/startups/06564dc8-4286-4c83-8a38-94d4226216ac', null),
('ST_631', 'Points', 'Points is the unified loyalty platform that brings all your points together in one place. Shop from our premium merchant network and earn points with every purchase, then use your accumulated points to pay for your next purchases at any partner store. You can also transfer your points from other loyalty programs to your unified Points wallet. One wallet, unlimited opportunities!', 'Financial Services & Fintech; Retail & E-commerce; Consumer Services', null, null, 'Pre-Seed', 'Makkah', 'Loyalty', 'https://papp.sa/', 'https://ecosystemsa.com/modules/startups/0f511559-9262-4864-839c-201e3f5f79b7', 'https://ecosystemsa.com/modules/startups/0f511559-9262-4864-839c-201e3f5f79b7', null),
('ST_632', 'HSInsight', 'industrial tech company helping factories use data, AI, and digital solutions to improve operations, reduce waste, and make faster decisions', 'Manufacturing; Technology', null, null, 'Pre-Seed', 'Eastern', 'B2B, Industrialtech, Smart Manufacturing, AI, Data', 'https://hsinsight.io/en/', 'https://ecosystemsa.com/modules/startups/3abfb9f1-7046-4334-a106-914d25857180', 'https://ecosystemsa.com/modules/startups/3abfb9f1-7046-4334-a106-914d25857180', null),
('ST_633', 'Rimal Semiconductors', 'Rimal Semiconductors is Saudi Arabia’s first fabless power semiconductor company, focused on building a sovereign, application-driven chip ecosystem. The company specializes in power devices—including MOSFETs, IGBTs, SiC, and GaN—serving critical sectors such as energy, industrial automation, mobility, and data infrastructure. Unlike traditional fabless companies, Rimal combines semiconductor design, application engineering, and localization strategies to deliver complete, market-ready solutions. Leveraging exclusive access to a broad portfolio of proven chip designs and a multi-foundry global supply chain, Rimal acts as a geopolitical hedge—ensuring resilient, secure, and flexible semiconductor supply. Through strategic partnerships and local integration, Rimal is enabling technology transfer, developing engineering talent, and positioning Saudi Arabia as a regional hub for semiconductor innovation in line with Vision 2030.', 'Technology; AI & Deep Tech', 'B2B', null, 'Seed', 'Riyadh', 'https://sa.linkedin.com/company/rimal-semiconductors', 'https://rimalsemiconductors.com/', 'https://ecosystemsa.com/modules/startups/089a1178-1fca-4e82-8882-48b5dd383262', 'https://ecosystemsa.com/modules/startups/089a1178-1fca-4e82-8882-48b5dd383262', 'Saudi Arabia'),
('ST_634', 'Pixconvey', 'Pixconvey is a Saudi company specializing in smart indoor mobility solutions, developing autonomous vehicles capable of mapless navigation with native Arabic language understanding. Serving airports, hospitals, and large facilities, Pixconvey delivers intelligent operational environments aligned with Vision 2030.', 'Travel, Tourism & Hospitality; Technology', null, null, 'Seed', 'Riyadh', 'Autonomous vehicles', 'https://www.pixconvey.net/', 'https://ecosystemsa.com/modules/startups/d57cd839-f6a2-4386-a928-343a1ea5c50a', 'https://ecosystemsa.com/modules/startups/d57cd839-f6a2-4386-a928-343a1ea5c50a', null),
('ST_635', 'Qanary', 'Qanary is a deep-tech oncology startup developing the world’s first Quantum-AI cancer diagnostic agent. Using a proprietary hybrid quantum-classical architecture, Qanary detects early-stage, sub-visual malignancies in just 8.24 seconds. By acting as an instant "Digital Second Opinion," we aim to eliminate the fatal 60-day global diagnostic backlog and redefine early cancer detection.', 'Health & Life Sciences', null, null, 'Pre-Seed', 'Riyadh', 'AI', 'https://www.qanary.net', 'https://ecosystemsa.com/modules/startups/cd5fcb7a-601e-444c-88b4-155f7c742804', 'https://ecosystemsa.com/modules/startups/cd5fcb7a-601e-444c-88b4-155f7c742804', null),
('ST_636', 'Nashir', 'An publisher is a modern Saudi platform to manage and disseminate software projects easily and professionally, enabling companies and developers to operate their applications on their own servers, cloud servers, or by providing circuits through us as an integrated and ready solution. The platform combines the speed of launch, infrastructure safety, automation of operations such as deployment, modernization, surveillance, and backup, to give you a global operation with a prosperous and productive service.', 'Technology', null, null, 'Pre-Seed', 'Riyadh', 'Tech', 'https://www.linkedin.com/company/nasher/', 'https://ecosystemsa.com/modules/startups/a2e10e1d-801d-4619-92f9-aad5d9fc9528', 'https://ecosystemsa.com/modules/startups/a2e10e1d-801d-4619-92f9-aad5d9fc9528', null),
('ST_637', 'Bookahospi', 'Bookahospi: Reshaping Global Mobility for Regulated Professions
Founded in Madrid in 2023, Bookahospi has helped over 2,500 professionals secure their licenses in Spain, Saudi Arabia, and 5 additional countries.
Trusted by leading institutions including Dr. Sulaiman Al-Habib Hospitals, the Ministry of Health of Saudi Arabia, and Bupa Spain — and powering a platform of more than 100,000 active users — Bookahospi has positioned itself as the answer to one of today’s most pressing global challenges: the shortage of qualified healthcare professionals.
The company is led by founders Sebastián Jiménez, Thalía Argüello, and Natalia Rodríguez, who share a clear vision:
“We are building the future of mobility for regulated professions — helping governments and professionals navigate the complexity of relocation, and turning that complexity into opportunity.”
Backed by F6 Ventures, Falak Angels, and Afaq Investments, Bookahospi is now scaling its AI-powered infrastructure across the GCC and Latin America.', 'Health & Life Sciences; Education, Research & Talent; Professional Services', null, null, 'Seed', 'Riyadh', 'Health', 'https://bookahospi.com/ar', 'https://ecosystemsa.com/modules/startups/713b677e-00b4-4d9d-95b0-bb85d1ed2190', 'https://ecosystemsa.com/modules/startups/713b677e-00b4-4d9d-95b0-bb85d1ed2190', null),
('ST_638', 'Byondbites', 'Byondbites turns what’s already in your kitchen into meals you actually want to eat. Byondbites is a food tech app that lets users scan their pantry and instantly get personalized recipe ideas based on what they have. We solve a simple but daily problem: food waste and mealtime decision fatigue. The app is live on iOS and Android with an active and growing user base across Saudi Arabia and the UAE. We built for this market intentionally. Food waste in the GCC is among the highest in the world, and consumers here are ready for smarter, culturally relevant solutions. We are currently raising our pre-seed round to fuel growth and the launch of Phase 2, which brings an AI-powered experience that takes the product to a completely different level. Byondbites has been selected to present at 2025 in August. Our expansion path: Saudi Arabia and UAE, then full GCC, then South Asia.', 'Food & Beverages', null, null, 'Pre-Seed', 'Makkah', 'FoodTech, D2C, Subscription', 'https://byondbites.com/', 'https://ecosystemsa.com/modules/startups/f8745cd8-1894-490f-82e1-8f2ba109ea2b', 'https://ecosystemsa.com/modules/startups/f8745cd8-1894-490f-82e1-8f2ba109ea2b', null),
('ST_639', 'Path Link', 'Path Link is an integrated digital platform that brings together individuals and businesses in one place, focusing on recruitment, training, consulting, and freelancing. It relies on smart technology and data analytics to connect users with the right opportunities, enabling them to develop their skills, offer their services, and build professional partnerships efficiently and seamlessly', 'Professional Services; HR & Recruitment', null, null, 'Pre-Seed', 'Riyadh', 'SaaS', 'https://www.linkedin.com/company/path-link/', 'https://ecosystemsa.com/modules/startups/af5983ee-e50a-45f3-9a24-c8c22b57e85d', 'https://ecosystemsa.com/modules/startups/af5983ee-e50a-45f3-9a24-c8c22b57e85d', null),
('ST_640', 'Senoz AI', 'SENOZ is an AI-powered healthcare intelligence platform designed to enhance clinical decision-making and improve healthcare efficiency through smart data-driven systems. The platform leverages advanced artificial intelligence to support doctors and medical teams in making faster, more accurate, and more reliable clinical decisions, reducing operational delays and improving patient outcomes. SENOZ operates at the intersection of healthcare, artificial intelligence, and digital transformation, enabling hospitals and healthcare providers to move from traditional reactive care to proactive, intelligent, and predictive healthcare systems.', 'Health & Life Sciences; Financial Services & Fintech', null, null, 'Pre-Seed', 'Riyadh', 'AI, Computer Vision', 'https://www.senoz.tech', 'https://ecosystemsa.com/modules/startups/13465eb1-df38-47ab-84c7-510c9f1b157f', 'https://ecosystemsa.com/modules/startups/13465eb1-df38-47ab-84c7-510c9f1b157f', null),
