('ST_665', 'Tuwaiq Technologies', 'AI that understands live video at national scale, engineered for Saudi Arabia''s security and operational sovereignty. Transforming disconnected cameras into unified intelligence networks, delivering verified insights that enable confident decision-making across critical infrastructure, borders, and mega-events.', 'Technology', null, null, 'Seed', 'Riyadh', 'AI Vision Intelligence', 'https://tuwaiqtechnologies.com/', 'https://ecosystemsa.com/modules/startups/8d7a9e0e-dfc9-48ba-ab06-2db438c2cbb3', 'https://ecosystemsa.com/modules/startups/8d7a9e0e-dfc9-48ba-ab06-2db438c2cbb3', null),
('ST_666', 'Printo Go', 'Printo Go is a mobile printing platform based in Riyadh that enables users to upload PDF files, select paper size, color, copies, finishing options, delivery location, and payment method from one simple application. Built on more than 14 years of hands-on printing experience, the platform transforms a traditionally manual ordering process into a clear, trackable digital workflow. Printo Go is operated by Star Business Company LLC and currently serves customers across Riyadh.', 'Professional Services', null, null, 'Pre-Seed', 'Riyadh', 'PrintTech, E-commerce', 'https://prinima.tech/', 'https://ecosystemsa.com/modules/startups/a21605c2-d3e0-4ea2-a962-f619827814e8', 'https://ecosystemsa.com/modules/startups/a21605c2-d3e0-4ea2-a962-f619827814e8', null),
('ST_667', 'Jabr', 'Jabr is an AI-powered accounting platform built for Saudi businesses. It helps companies manage accounting, bookkeeping, VAT, Zakat, payroll, inventory, financial statements, and tax filings in one place while following SOCPA accounting standards and ZATCA regulations. Businesses can use Jabr as a complete accounting system on its own, or connect it with AI assistants like ChatGPT or Claude through MCP. Once connected, users can simply ask for what they need in plain language—such as recording expenses, processing invoices, generating financial reports, preparing VAT returns, running payroll, or analyzing business performance—and Jabr securely executes those actions inside the accounting system. Jabr understands each company''s structure, accounting setup, and transaction history, allowing it to recommend the correct accounting treatment, automate repetitive work, and generate accurate reports ready for review. From daily bookkeeping to regulatory filings, Jabr turns accounting tasks that normally take hours or days into work completed in minutes.', 'Technology', null, null, 'Seed', 'Riyadh', 'SaaS, Accounting, AI', 'https://jabrhq.com', 'https://ecosystemsa.com/modules/startups/d982b2ee-0110-449d-b25f-a444a8af8db4', 'https://ecosystemsa.com/modules/startups/d982b2ee-0110-449d-b25f-a444a8af8db4', null),
('ST_668', 'TotalPay', 'TotalPay is a SAMA-approved E-commerce Payment Technical Service Provider offering secure and scalable payment gateway and orchestration solutions. Its platform enables businesses to accept and manage digital payments through multi-gateway routing, payment links, recurring payments, tokenization, QR payments, plugins, APIs, and comprehensive merchant reporting tools.', 'Financial Services & Fintech; Technology', null, null, 'Series A', 'Riyadh', 'Fintech, Payment', 'https://totalpay.global/', 'https://ecosystemsa.com/modules/startups/e5c9ccd3-ab2f-4d07-88cc-85c3ce54593b', 'https://ecosystemsa.com/modules/startups/e5c9ccd3-ab2f-4d07-88cc-85c3ce54593b', null),
('ST_669', 'Sabura', 'An Arab educational platform that provides teachers with an interactive screen and a combination of smart tools to manage quotas and class activities from one place, works directly across the brow, and helps teachers and schools to provide more interactive and structured lessons, both within the classroom and in distance education.', 'Education, Research & Talent', null, null, 'Pre-Seed', 'Riyadh', 'Edtech, SaaS, AI', 'https://sabura.app', 'https://ecosystemsa.com/modules/startups/1128aaed-583f-40e7-826f-4fc9ee0cce7a', 'https://ecosystemsa.com/modules/startups/1128aaed-583f-40e7-826f-4fc9ee0cce7a', null),
('ST_670', 'Saffron Boxes', 'The SaffronBoxes is a specialised shop in Saudi Arabia, providing a variety of saffrons for use in Arabic and Saudi coffee, cooking, hospitality and gifts. The products of the Zafran Zafran Zubir al-Naqil, Fran Abu Shabal al-Sha &apos; id, Fran Afr Shu &apos; s França and França &apos; s al-Sah are fitting options.', 'Food & Beverages', null, null, 'Seed', 'Riyadh', 'E-commerce', 'https://saffronboxes.com/', 'https://ecosystemsa.com/modules/startups/c43f1364-4b07-4cb4-908d-f1f0c6e54abd', 'https://ecosystemsa.com/modules/startups/c43f1364-4b07-4cb4-908d-f1f0c6e54abd', null),
('ST_671', 'Bookra', 'Bookra is an Arabic-first property management and booking platform for chalets, rest houses, camps, and short-term rental properties, focused primarily on the Saudi market. It helps owners manage reservations, availability calendars, deposits and remaining balances, expenses, electronic contracts, occupancy, and operational reports from one simple dashboard. Owners can also create a dedicated booking page for their properties and share availability directly with guests.', 'Travel, Tourism & Hospitality', null, null, 'Pre-Seed', 'Eastern', 'SaaS, Hospitality Tech, Property Management, Booking Management', 'https://bookra.io/', 'https://ecosystemsa.com/modules/startups/becd67c7-ea5a-41eb-85e5-645a03f8891e', 'https://ecosystemsa.com/modules/startups/becd67c7-ea5a-41eb-85e5-645a03f8891e', null),
